  "verbo-142": {"promptNative":"Ninguém pensou que nós ___ capazes de tal façanha. (être = ser)","explain":"'Être' no imperfeito do subjuntivo (forma nous) é 'fussions', não o pretérito 'fûmes'.","wrongNote":"Nesta construção literária no passado o subjuntivo passa ao imperfeito do subjuntivo: com 'nous' (nós), 'être' é “fussions”.","distractorNotes":{"étions":"o imperfeito de 'être' — sujeito correto, tempo/modo errado: aqui é preciso o imperfeito do subjuntivo.","soyons":"o presente do subjuntivo de 'être' — sujeito correto, tempo/modo errado: aqui é preciso o imperfeito do subjuntivo.","fûmes":"outra forma de 'être' — não concorda com 'nous' (nós) no imperfeito do subjuntivo aqui."}},
  "verbo-143": {"promptNative":"Ele teria desejado que eles ___ em sua ajuda. (venir = vir)","explain":"'Venir' no imperfeito do subjuntivo (forma ils) é 'vinssent', diferente do pretérito 'vinrent'.","wrongNote":"Nesta construção literária no passado o subjuntivo passa ao imperfeito do subjuntivo: com 'ils/elles' (eles), 'venir' é “vinssent”.","distractorNotes":{"venaient":"outra forma de 'venir' — não concorda com 'ils/elles' (eles) no imperfeito do subjuntivo aqui.","vinrent":"outra forma de 'venir' — não concorda com 'ils/elles' (eles) no imperfeito do subjuntivo aqui.","viennent":"o presente do subjuntivo de 'venir' — sujeito correto, tempo/modo errado: aqui é preciso o imperfeito do subjuntivo."}},
  "verbo-144": {"promptNative":"Embora eles ___ previsto tudo, o plano fracassou. (avoir = ter)","explain":"Depois de 'bien que' em um passado literário, 'avoir' (forma ils) toma o imperfeito do subjuntivo 'eussent', não o pretérito 'eurent'.","wrongNote":"Nesta construção literária no passado o subjuntivo passa ao imperfeito do subjuntivo: com 'ils/elles' (eles), 'avoir' é “eussent”.","distractorNotes":{"avaient":"o imperfeito de 'avoir' — sujeito correto, tempo/modo errado: aqui é preciso o imperfeito do subjuntivo.","eurent":"outra forma de 'avoir' — não concorda com 'ils/elles' (eles) no imperfeito do subjuntivo aqui.","aient":"o presente do subjuntivo de 'avoir' — sujeito correto, tempo/modo errado: aqui é preciso o imperfeito do subjuntivo."}},
  "verbo-145": {"promptNative":"Teria sido melhor que ele ___ de vergonha antes de confessar. (mourir = morrer)","explain":"'Mourir' no imperfeito do subjuntivo é 'mourût' (circunflexo), a forma literária dramática depois de 'il eût mieux valu'.","wrongNote":"Nesta construção literária no passado o subjuntivo passa ao imperfeito do subjuntivo: com 'il/elle' (ele/ela), 'mourir' é “mourût”.","distractorNotes":{"mourait":"outra forma de 'mourir' — não concorda com 'il/elle' (ele/ela) no imperfeito do subjuntivo aqui.","mourut":"outra forma de 'mourir' — não concorda com 'il/elle' (ele/ela) no imperfeito do subjuntivo aqui.","meure":"outra forma de 'mourir' — não concorda com 'il/elle' (ele/ela) no imperfeito do subjuntivo aqui."}},
  "verbo-146": {"promptNative":"Ele teria precisado ___ sob uma estrela melhor. (naître = nascer)","explain":"'Naître' no imperfeito do subjuntivo é 'naquît' (circunflexo), diferente do pretérito 'naquit'.","wrongNote":"Nesta construção literária no passado o subjuntivo passa ao imperfeito do subjuntivo: com 'il/elle' (ele/ela), 'naître' é “naquît”.","distractorNotes":{"naquit":"outra forma de 'naître' — não concorda com 'il/elle' (ele/ela) no imperfeito do subjuntivo aqui.","naissait":"outra forma de 'naître' — não concorda com 'il/elle' (ele/ela) no imperfeito do subjuntivo aqui.","naisse":"outra forma de 'naître' — não concorda com 'il/elle' (ele/ela) no imperfeito do subjuntivo aqui."}},
  "verbo-147": {"promptNative":"Quando ela chegou, ele já ___ havia uma hora. (partir = ir embora)","explain":"'Partir' usa 'être' como auxiliar, então o mais-que-perfeito é 'était parti' — uma ação concluída antes de outro fato passado.","wrongNote":"Uma ação anterior a outro momento passado usa o mais-que-perfeito; com 'il/elle' (ele/ela) é “était parti”.","distractorNotes":{"est parti":"outra forma de 'partir' — não concorda com 'il/elle' (ele/ela) no mais-que-perfeito aqui.","fut parti":"outra forma de 'partir' — não concorda com 'il/elle' (ele/ela) no mais-que-perfeito aqui.","avait parti":"outra forma de 'partir' — não concorda com 'il/elle' (ele/ela) no mais-que-perfeito aqui."}},
  "verbo-148": {"promptNative":"Nós ___ bem o trabalho antes de ele chegar. (finir = terminar)","explain":"O mais-que-perfeito 'avions fini' marca uma ação concluída antes de outra passada; 'eûmes fini' é o raro pretérito anterior, não o que se precisa aqui.","wrongNote":"Uma ação anterior a outro momento passado usa o mais-que-perfeito; com 'nous' (nós) é “avions fini”.","distractorNotes":{"finissions":"outra forma de 'finir' — não concorda com 'nous' (nós) no mais-que-perfeito aqui.","avons fini":"outra forma de 'finir' — não concorda com 'nous' (nós) no mais-que-perfeito aqui.","eûmes fini":"outra forma de 'finir' — não concorda com 'nous' (nós) no mais-que-perfeito aqui."}},
  "verbo-149": {"promptNative":"Eu não ___ recomendar com muita insistência a maior prudência. (savoir = saber/poder)","explain":"O literário 'je ne saurais' usa o condicional de 'savoir' com o sentido cortês de 'no podría' — uma expressão refinada.","wrongNote":"O condicional (faria) de 'savoir' com 'je' (eu) é “saurais”.","distractorNotes":{"susse":"outra forma de 'savoir' — não concorda com 'je' (eu) no condicional aqui.","savais":"outra forma de 'savoir' — não concorda com 'je' (eu) no condicional aqui.","saurai":"outra forma de 'savoir' — não concorda com 'je' (eu) no condicional aqui."}},
